// tests/uuidv7.test.ts — proves the team UUIDv7 generation standard is in force on both paths:
//   1. DB-side: a fresh insert's PK is generated by the Postgres 18 `uuidv7()` column default
//      (migration 0039 + schema.ts `.default(sql`uuidv7()`)`).
//   2. App-side: `Bun.randomUUIDv7()` (used for persisted run/turn/seed IDs) produces v7.
// A v7 UUID has version nibble `7` (15th hex digit) and variant bits 10xx (17th digit ∈ 8/9/a/b).
import { test, expect, beforeAll, afterAll } from 'bun:test';
import { eq } from 'drizzle-orm';
import { db, users, challenges } from '../src/db/client';

const V7_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const UID = '00000000-0000-0000-0000-00000c700001';
const MARK = 'ZUUIDV7TEST';

// explicit hook timeout — see the long note in license-provisioning.test.ts; bun ignores
// bunfig's [test] timeout for hooks, so a slow one fails as "(unnamed) [5003ms]" with no file/cause.
beforeAll(async () => {
  await db
    .insert(users)
    .values({ id: UID, email: 'uuidv7@test', name: 'UUIDv7 Tester', avatar_initials: 'U7' })
    .onConflictDoNothing();
}, 30_000);

afterAll(async () => {
  await db.delete(challenges).where(eq(challenges.submitter_id, UID));
  await db.delete(users).where(eq(users.id, UID));
}, 30_000);

test('Bun.randomUUIDv7() returns a v7 UUID', () => {
  expect(Bun.randomUUIDv7()).toMatch(V7_RE);
});

test('a DB-generated primary key uses the uuidv7() default', async () => {
  const [row] = await db
    .insert(challenges)
    .values({
      title: `${MARK} v7 default`,
      work_area: 'data',
      submitter_id: UID,
      tenant_id: UID,
      status: 'voting',
      week: '2026-W21',
    })
    .returning();
  expect(row!.id).toMatch(V7_RE);
});
